                           LoadMemberPort loadMemberPort, CountActiveLoansPort countActiveLoansPort,
                           LoadActiveReservationsPort loadActiveReservationsPort,
                           SaveReservationPort saveReservationPort, CheckCreditPort checkCreditPort) {
