        this.saveBookPort = saveBookPort;
        this.saveLoanPort = saveLoanPort;
        this.loadMemberPort = loadMemberPort;
        this.countActiveLoansPort = countActiveLoansPort;
        this.loadActiveReservationsPort = loadActiveReservationsPort;
        this.saveReservationPort = saveReservationPort;
        this.checkCreditPort = checkCreditPort;
    }

    @Override
    public Loan loanBook(LoanBookCommand command) {
        Member member = loadMemberPort.loadMember(command.memberId())
                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
        member.ensureCanBorrow(countActiveLoansPort.countActiveLoans(member.getId()));

        Book book = loadBookPort.loadBook(command.bookId())
                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
        ReservationQueue queue = new ReservationQueue(book.getId(),
                loadActiveReservationsPort.loadWaitingReservations(book.getId()));
        if (book.getStatus() == BookStatus.AVAILABLE) {
            queue.ensureCanBorrow(member.getId());
        }
        // 대출할 수 없는 책이면 외부 신용조회를 부르지 않는다.
        book.ensureLoanable();

        CreditCheck creditCheck = checkCreditPort.checkCredit(member, Instant.now());
        Loan loan = book.loanTo(member.getId(), Objects.requireNonNullElseGet(command.loanedAt(), LocalDate::now),
                creditCheck);
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        queue.fulfillFor(member.getId()).ifPresent(saveReservationPort::saveReservation);
        return loan;
    }
}

