package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

import java.util.Arrays;
import java.util.List;

class LoanMapper {

    Loan toDomain(LoanJpaEntity entity) {
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(),
                entity.getLoanedAt(), entity.getDueAt(), entity.getReturnedAt(), toDomain(entity.getCreditCheck()));
    }

    LoanJpaEntity toEntity(Loan loan) {
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), toEntity(loan.getCreditCheck()));
    }

    private CreditCheck toDomain(CreditCheckEmbeddable embeddable) {
        if (embeddable == null) {
            return null;
        }
        return new CreditCheck(embeddable.getRequestedAt(), embeddable.getApproved(), embeddable.getScore(),
                splitReasonCodes(embeddable.getReasonCodes()), embeddable.getCheckedAt(),
                embeddable.getProviderName(), embeddable.getProviderVersion());
    }

    private CreditCheckEmbeddable toEntity(CreditCheck creditCheck) {
        if (creditCheck == null) {
            return null;
        }
        return new CreditCheckEmbeddable(creditCheck.requestedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(",", creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    private List<String> splitReasonCodes(String reasonCodes) {
        if (reasonCodes == null || reasonCodes.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(reasonCodes.split(","));
    }
}

